const payload = $input.first().json;
const original = payload.original;
const catalogo = payload.catalogo;
const extraido = payload.extraido;
const registroId = payload.registro_id;

const normalizar = (texto) => String(texto || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

let monto = extraido.monto_total ?? extraido.monto ?? extraido.total ?? null;
if (typeof monto === 'string') {
  monto = Number(monto.replace(/\./g, '').replace(/,/g, '').replace(/[^\d-]/g, ''));
}
if (typeof monto === 'number' && !Number.isInteger(monto)) {
  const match = String(original.texto || '').match(/(\d{1,3}(?:\.\d{3})+)/);
  if (match) monto = Number(match[1].replace(/\./g, ''));
  else monto = Math.round(monto);
}
if (!Number.isFinite(monto) || monto <= 0) monto = null;

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Santiago' }).format(new Date());
let fecha = extraido.fecha ?? extraido.fecha_gasto ?? hoy;
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(fecha))) fecha = hoy;

const buscar = (lista, valor) => {
  const objetivo = normalizar(valor);
  if (!objetivo) return null;
  return lista.find(item => normalizar(item.nombre) === objetivo) || null;
};

const medio = buscar(catalogo.medios_pago, extraido.medio_pago ?? extraido.medioPago ?? null);
const categoria = buscar(catalogo.categorias, extraido.categoria ?? extraido.categoria_gasto ?? null);
const proveedor = (extraido.proveedor ?? extraido.comercio ?? extraido.local ?? extraido.tienda ?? '').trim() || null;
const proyectoTexto = (extraido.proyecto ?? extraido.proyecto_nombre ?? '').trim() || null;

const datos = {
  proyecto_texto: proyectoTexto,
  proyecto_id: null,
  proyecto_nombre: null,
  proyecto_score: 0,
  monto_total: monto,
  fecha,
  proveedor,
  medio_pago_id: medio ? medio.id : null,
  medio_pago_nombre: medio ? medio.nombre : null,
  categoria_id: categoria ? categoria.id : null,
  categoria_nombre: categoria ? categoria.nombre : null,
  descripcion: (extraido.descripcion ?? extraido.detalle ?? '').trim() || null,
  confianza: (extraido.confianza && typeof extraido.confianza === 'object') ? extraido.confianza : {}
};

const faltantes = [];
if (!proyectoTexto) faltantes.push('proyecto');
if (!monto) faltantes.push('monto_total');
if (!fecha) faltantes.push('fecha');
if (!proveedor) faltantes.push('proveedor');
if (!medio) faltantes.push('medio_pago');

return [{ json: { registro_id: registroId, original, catalogo, datos, faltantes, proyecto_texto: proyectoTexto } }];

const base = $('Normalizar extraccion').first().json;
const candidatos = $input.all().map(item => item.json).filter(c => c && c.nombre);
const datos = { ...base.datos };
const faltantes = [...base.faltantes];

let proyectoId = null;
let proyectoNombre = null;
let proyectoScore = 0;
let candidatosParaPregunta = [];

if (candidatos.length > 0) {
  const best = candidatos[0];
  const second = candidatos[1];
  const score = Number(best.score);
  const gap = second ? score - Number(second.score) : 1;

  if (score >= 0.55 && gap >= 0.10) {
    proyectoId = best.id;
    proyectoNombre = best.nombre;
    proyectoScore = score;
    const idx = faltantes.indexOf('proyecto');
    if (idx >= 0) faltantes.splice(idx, 1);
  } else {
    candidatosParaPregunta = candidatos.slice(0, 3);
  }
}

if (proyectoId === null && !faltantes.includes('proyecto')) {
  faltantes.push('proyecto');
}

datos.proyecto_id = proyectoId;
datos.proyecto_nombre = proyectoNombre;
datos.proyecto_score = proyectoScore;

return [{ json: { ...base, datos, faltantes, candidatos: candidatosParaPregunta } }];

const base = $input.first().json;
const datos = base.datos;
const faltantes = base.faltantes;
const original = base.original;
const registroId = base.registro_id;

const prioridad = ['proyecto', 'monto_total', 'fecha', 'proveedor', 'medio_pago'];
const campoPendiente = prioridad.find(campo => faltantes.includes(campo)) || null;

const money = new Intl.NumberFormat('es-CL', {
  style: 'currency',
  currency: 'CLP',
  maximumFractionDigits: 0
}).format(datos.monto_total || 0);
const fecha = datos.fecha ? datos.fecha.split('-').reverse().join('-') : '(sin fecha)';

const resumen = [
  'Registraré este gasto:',
  '',
  `🏗️ Proyecto: ${datos.proyecto_nombre || '(sin proyecto)'}`,
  `💵 Monto: ${money}`,
  `📅 Fecha: ${fecha}`,
  `🏪 Proveedor: ${datos.proveedor || '(sin proveedor)'}`,
  `💳 Pago: ${datos.medio_pago_nombre || '(sin medio de pago)'}`,
  `📂 Categoría: ${datos.categoria_nombre || '(sin categoría)'}`
].join('\n');

let pregunta = null;
if (campoPendiente === 'proyecto') {
  const opciones = (base.candidatos || [])
    .map(c => `- ${c.nombre} (${Math.round(Number(c.score) * 100)}%)`)
    .join('\n');
  pregunta = opciones
    ? `¿A qué proyecto corresponde este gasto?\n\n${opciones}`
    : '¿A qué proyecto corresponde este gasto?';
}
if (campoPendiente === 'monto_total') pregunta = '¿Cuál fue el monto total del gasto?';
if (campoPendiente === 'fecha') pregunta = '¿Qué fecha tiene el gasto?';
if (campoPendiente === 'proveedor') pregunta = '¿En qué proveedor o local fue la compra?';
if (campoPendiente === 'medio_pago') pregunta = '¿Con qué medio de pago se realizó?';

const sinDatos = !datos.proyecto_texto && !datos.monto_total && !datos.proveedor && !datos.medio_pago_id && !datos.categoria_id && !datos.descripcion;
const estado = sinDatos ? 'cancelado' : (campoPendiente ? 'falta_dato' : 'pendiente_confirmacion');
const modo = sinDatos ? 'no_gasto' : (campoPendiente ? 'falta_dato' : 'confirmacion');
const mensajeNoGasto = 'No pude identificar un gasto en tu mensaje. Env?a algo como:\n"Anota 12.500 en Copec, d?bito, obra Pe?uelas, bencina."\nTambi?n puedes usar /cancelar.';
const errorDetalle = sinDatos ? 'No se identific? un gasto' : null;

return [{
  json: {
    ...base,
    registro_id: registroId,
    telegram_chat_id: original.telegram_chat_id,
    estado,
    modo,
    campo_pendiente: sinDatos ? null : campoPendiente,
    resumen,
    pregunta,
    mensaje_no_gasto: mensajeNoGasto,
    error_detalle: errorDetalle
  }
}];

const input = $input.first().json;
const original = input.original;
const catalogo = input.catalogo;
const registroId = input.registro_id;
const contexto = input.contexto || {};
const campoPendiente = input.campo_pendiente || null;
const esContinuacion = !!input.es_continuacion;

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Santiago' }).format(new Date());
const proyectos = catalogo.proyectos.map(p => `- ${p.nombre} | ${(p.alias || []).join(', ')}`).join('\n');
const medios = catalogo.medios_pago.map(m => `- ${m.nombre}`).join('\n');
const categorias = catalogo.categorias.map(c => `- ${c.nombre}`).join('\n');

const contextoTexto = esContinuacion
  ? `\nEST?S COMPLETANDO UN GASTO YA INICIADO.
DATOS ACTUALES:
${JSON.stringify(contexto, null, 2)}
CAMPO_PENDIENTE: ${campoPendiente}
El usuario responde: "${original.texto}"
Devuelve el JSON completo, manteniendo los datos actuales que no cambien y actualizando el campo pendiente.\n`
  : '';

const prompt = `Eres el m?dulo de extracci?n de datos de compras de Constructora MYRA.
Recibes la transcripci?n de una nota de voz o un mensaje de texto de un jefe de obra chileno.
Tu ?nica tarea es extraer los datos del gasto y devolver un JSON v?lido.

REGLAS OBLIGATORIAS
1. No inventes datos. Si un campo no aparece, usa null.
2. No escribas explicaciones, markdown ni texto fuera del JSON.
3. Los montos son pesos chilenos (CLP), enteros y sin puntos ni decimales.
   - "45 mil" -> 45000
   - "45.990" -> 45990
   - "cuarenta y cinco mil novecientos noventa" -> 45990
4. La fecha debe ser ISO 8601 (YYYY-MM-DD). Usa FECHA_ACTUAL si dice "hoy".
5. El proyecto debe ser uno de PROYECTOS o un alias. Si no se menciona, usa null.
6. El medio de pago debe ser uno de MEDIOS_PAGO. Si no coincide, usa null.
7. La categor?a debe ser una de CATEGORIAS. Si no est?s seguro, usa null.
8. La descripci?n es breve: qu? se compr?.
9. La confianza es un n?mero entre 0 y 1 por cada campo.
10. Si el mensaje es un saludo, una pregunta o no describe una compra, devuelve todas las claves en null, incluida descripcion.

FORMATO EXACTO DE SALIDA (no cambies las claves):
{
  "proyecto": "nombre oficial o alias, o null",
  "monto_total": 12500,
  "fecha": "YYYY-MM-DD o null",
  "proveedor": "nombre del local o null",
  "medio_pago": "nombre exacto del cat?logo o null",
  "categoria": "nombre exacto del cat?logo o null",
  "descripcion": "qu? se compr?, sin incluir el proveedor"
}
No uses la clave "monto"; usa "monto_total".
No incluyas el proveedor dentro de "descripcion"; usa el campo "proveedor".
${contextoTexto}
FECHA_ACTUAL: ${hoy}

PROYECTOS (nombre oficial | alias):
${proyectos}

MEDIOS_PAGO:
${medios}

CATEGORIAS:
${categorias}

TEXTO DEL USUARIO:
"""
${original.texto}
"""

Devuelve solo el JSON.`;

return [{ json: { registro_id: registroId, original, catalogo, contexto, campo_pendiente: campoPendiente, es_continuacion: esContinuacion, prompt } }];

const base = $('Preparar prompt').first().json;
const raw = $input.first().json;

const parsePosible = (value) => {
  if (typeof value !== 'string') return value;
  const limpio = value.replace(/```json/gi, '').replace(/```/g, '').trim();
  try {
    return JSON.parse(limpio);
  } catch (error) {
    return {};
  }
};

let parsed = raw && raw.output ? raw.output : raw;
if (parsed && typeof parsed.text === 'string') parsed = parsed.text;
parsed = parsePosible(parsed);
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) parsed = {};

const prev = base.contexto || {};
const merged = {
  proyecto: prev.proyecto_nombre || prev.proyecto_texto || null,
  monto_total: prev.monto_total ?? null,
  fecha: prev.fecha ?? null,
  proveedor: prev.proveedor ?? null,
  medio_pago: prev.medio_pago_nombre ?? null,
  categoria: prev.categoria_nombre ?? null,
  descripcion: prev.descripcion ?? null
};
const incoming = {
  proyecto: parsed.proyecto ?? parsed.proyecto_nombre ?? null,
  monto_total: parsed.monto_total ?? parsed.monto ?? null,
  fecha: parsed.fecha ?? parsed.fecha_gasto ?? null,
  proveedor: parsed.proveedor ?? parsed.comercio ?? parsed.local ?? parsed.tienda ?? null,
  medio_pago: parsed.medio_pago ?? parsed.medioPago ?? null,
  categoria: parsed.categoria ?? parsed.categoria_gasto ?? null,
  descripcion: parsed.descripcion ?? parsed.detalle ?? null
};
for (const key of Object.keys(merged)) {
  if (incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '') merged[key] = incoming[key];
}

return [{ json: { registro_id: base.registro_id, original: base.original, catalogo: base.catalogo, extraido: merged } }];

const input = $input.first().json;
const original = $('Cuando se ejecuta').first().json;
const catalogo = $('Maestras').first().json;
const esContinuacion = input.json_extraido !== undefined && input.estado === 'falta_dato';
let contexto = {};
if (esContinuacion) {
  try {
    contexto = typeof input.json_extraido === 'string' ? JSON.parse(input.json_extraido) : input.json_extraido;
  } catch (error) {
    contexto = {};
  }
}
return [{
  json: {
    registro_id: input.id,
    original,
    catalogo,
    contexto,
    campo_pendiente: esContinuacion ? input.campo_pendiente : null,
    es_continuacion: esContinuacion
  }
}];
